struct App {
    db: Mutex<Connection>,
    secret: String,
    credential_signature: Vec<u8>,
    csrf: String,
}

impl App {
    fn db(&self) -> Result<MutexGuard<'_, Connection>> {
        self.db
            .lock()
            .map_err(|_| AppError::Internal("Database lock poisoned".into()))
    }
    fn check_csrf(&self, fields: &Fields) -> Result<()> {
        let token = URL_SAFE_NO_PAD
            .decode(field(fields, "csrf"))
            .map_err(|_| AppError::Forbidden)?;
        let mut mac = HmacSha256::new_from_slice(self.secret.as_bytes()).unwrap();
        mac.update(b"quizzy moderator csrf v1");
        mac.verify_slice(&token).map_err(|_| AppError::Forbidden)
    }
}

#[derive(Debug)]
enum AppError {
    NotFound,
    Forbidden,
    BadRequest,
    Internal(String),
}
impl From<rusqlite::Error> for AppError {
    fn from(error: rusqlite::Error) -> Self {
        Self::Internal(error.to_string())
    }
}
