            .headers()
            .get(header::AUTHORIZATION)
            .and_then(|h| h.to_str().ok())
            .and_then(|h| h.split_once(' '))
            .filter(|(scheme, _)| scheme.eq_ignore_ascii_case("Basic"))
            .and_then(|(_, credentials)| STANDARD.decode(credentials).ok())
            .is_some_and(|credentials| {
                let mut mac = HmacSha256::new_from_slice(app.secret.as_bytes()).unwrap();
                mac.update(&credentials);
                mac.verify_slice(&app.credential_signature).is_ok()
            });
        if !authorized {
            return (
                StatusCode::UNAUTHORIZED,
                [
                    (
                        header::WWW_AUTHENTICATE,
                        "Basic realm=\"Quizzy Moderator\", charset=\"UTF-8\"",
                    ),
                    (header::CACHE_CONTROL, "no-store"),
                ],
                "Moderator authentication required",
            )
                .into_response();
        }
    }
    let mut response = next.run(request).await;
    let headers = response.headers_mut();
    headers.insert(header::X_CONTENT_TYPE_OPTIONS, "nosniff".parse().unwrap());
    headers.insert(header::CONTENT_SECURITY_POLICY, "default-src 'self'; script-src 'self'; style-src 'self'; font-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'".parse().unwrap());
    headers.insert(header::REFERRER_POLICY, "same-origin".parse().unwrap());
    if moderator {
        headers.insert(header::CACHE_CONTROL, "no-store".parse().unwrap());
        headers.insert(header::VARY, "Authorization".parse().unwrap());
    }
    response
}

fn field<'a>(fields: &'a Fields, key: &str) -> &'a str {
    fields.get(key).map(String::as_str).unwrap_or("")
}
fn quiz_title(db: &Connection, id: i64) -> Result<String> {
    db::title(db, id)?.ok_or(AppError::NotFound)
}
fn find_question(db: &Connection, quiz_id: i64, id: i64) -> Result<Question> {
    db::questions(db, quiz_id)?
        .into_iter()
        .find(|q| q.id == id)
        .ok_or(AppError::NotFound)
}
fn go_to_quiz(id: i64) -> Response {
    Redirect::to(&format!("/moderate/quizzes/{id}")).into_response()
}

async fn up(State(app): State<AppState>) -> Result<&'static str> {
    app.db()?.query_row("SELECT 1", [], |_| Ok(()))?;
    Ok("OK")
}

async fn quizzes(State(app): State<AppState>) -> Result<Html<String>> {
    let db = app.db()?;
    let mut stmt = db.prepare("SELECT q.id, q.title, COUNT(s.id), COALESCE(SUM(s.active), 0) FROM quizzes q LEFT JOIN questions s ON s.quiz_id = q.id GROUP BY q.id ORDER BY q.id DESC")?;
    let quizzes = stmt
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)))?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    Ok(Html(views::quiz_list(&quizzes)))
}
async fn import_form(State(app): State<AppState>) -> Html<String> {
    Html(views::import_form("", &app.csrf, &[]))
}

async fn import_quiz(State(app): State<AppState>, Form(fields): Form<Fields>) -> Result<Response> {
    app.check_csrf(&fields)?;
    let json = field(&fields, "quiz_json");
    let (title, questions) = match contents::parse(json) {
        Ok(quiz) => quiz,
        Err(messages) => {
            let messages: Vec<_> = messages.iter().map(String::as_str).collect();
            return Ok((
                StatusCode::UNPROCESSABLE_ENTITY,
                Html(views::import_form(json, &app.csrf, &messages)),
            )
                .into_response());
        }
    };
    let mut db = app.db()?;
    let id = contents::insert(&mut db, &title, &questions)?;
    Ok(go_to_quiz(id))
}

async fn export_quiz(State(app): State<AppState>, Path(id): Path<i64>) -> Result<Html<String>> {
    let db = app.db()?;
    let title = quiz_title(&db, id)?;
    let quiz = contents::QuizContents::from_quiz(title.clone(), db::questions(&db, id)?);
    let json = serde_json::to_string_pretty(&quiz)
        .map_err(|error| AppError::Internal(error.to_string()))?;
    Ok(Html(views::export_quiz(id, &title, &json)))
}

