    Html(views::quiz_form(None, "", &app.csrf, &[]))
}
async fn edit_quiz(State(app): State<AppState>, Path(id): Path<i64>) -> Result<Html<String>> {
    let title = quiz_title(&*app.db()?, id)?;
    Ok(Html(views::quiz_form(Some(id), &title, &app.csrf, &[])))
}
async fn show_quiz(State(app): State<AppState>, Path(id): Path<i64>) -> Result<Html<String>> {
    let db = app.db()?;
    Ok(Html(views::quiz(
        id,
        &quiz_title(&db, id)?,
        &db::questions(&db, id)?,
        &app.csrf,
    )))
}
async fn create_quiz(State(app): State<AppState>, Form(fields): Form<Fields>) -> Result<Response> {
    save_quiz(&app, None, &fields)
}
async fn update_quiz(
    State(app): State<AppState>,
    Path(id): Path<i64>,
    Form(fields): Form<Fields>,
) -> Result<Response> {
    save_quiz(&app, Some(id), &fields)
}
fn save_quiz(app: &App, id: Option<i64>, fields: &Fields) -> Result<Response> {
    app.check_csrf(fields)?;
    let db = app.db()?;
    if let Some(id) = id {
        quiz_title(&db, id)?;
    }
    let title = field(fields, "title");
    if title.trim().is_empty() {
        return Ok((
            StatusCode::UNPROCESSABLE_ENTITY,
            Html(views::quiz_form(
                id,
                title,
                &app.csrf,
                &["Title is required"],
            )),
        )
            .into_response());
    }
    let id = match id {
        Some(id) => {
            db.execute(
                "UPDATE quizzes SET title = ? WHERE id = ?",
                params![title.trim(), id],
            )?;
            id
        }
        None => {
            db.execute("INSERT INTO quizzes(title) VALUES (?)", [title.trim()])?;
            db.last_insert_rowid()
        }
    };
    Ok(go_to_quiz(id))
}
async fn delete_quiz(
    State(app): State<AppState>,
    Path(id): Path<i64>,
    Form(fields): Form<Fields>,
) -> Result<Redirect> {
    app.check_csrf(&fields)?;
    let db = app.db()?;
    quiz_title(&db, id)?;
    db.execute("DELETE FROM quizzes WHERE id = ?", [id])?;
    Ok(Redirect::to("/moderate"))
}
